import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOutfit = makeLoadFont('Outfit');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: outfitFamily } = loadOutfit();

// Pre-calculated trading candle data to ensure clean, high-performance deterministic animation
const CANDLE_DATA = [
  { open: 0.14, close: 0.17, low: 0.11, high: 0.20 }, // 0
  { open: 0.17, close: 0.15, low: 0.13, high: 0.19 }, // 1
  { open: 0.15, close: 0.12, low: 0.09, high: 0.16 }, // 2
  { open: 0.12, close: 0.16, low: 0.10, high: 0.18 }, // 3
  { open: 0.16, close: 0.22, low: 0.14, high: 0.24 }, // 4
  { open: 0.22, close: 0.20, low: 0.18, high: 0.25 }, // 5
  { open: 0.20, close: 0.25, low: 0.17, high: 0.27 }, // 6
  { open: 0.25, close: 0.23, low: 0.21, high: 0.29 }, // 7
  { open: 0.23, close: 0.28, low: 0.20, high: 0.31 }, // 8
  { open: 0.28, close: 0.35, low: 0.26, high: 0.37 }, // 9
  { open: 0.35, close: 0.32, low: 0.30, openY: 0.35, high: 0.39 }, // 10
  { open: 0.32, close: 0.30, low: 0.28, high: 0.34 }, // 11
  { open: 0.30, close: 0.25, low: 0.23, openY: 0.32, high: 0.32 }, // 12
  { open: 0.25, close: 0.27, low: 0.22, high: 0.29 }, // 13
  { open: 0.27, close: 0.23, low: 0.21, high: 0.28 }, // 14
  { open: 0.23, close: 0.21, low: 0.19, high: 0.25 }, // 15
  { open: 0.21, close: 0.18, low: 0.16, high: 0.23 }, // 16
  { open: 0.18, close: 0.19, low: 0.15, high: 0.21 }, // 17
  { open: 0.19, close: 0.21, low: 0.17, high: 0.24 }, // 18 (Local dip)
  { open: 0.21, close: 0.25, low: 0.20, high: 0.28 }, // 19 (TRADE ENTRY POSITION - THE DIP BOTTOM!)
  { open: 0.25, close: 0.32, low: 0.24, high: 0.34 }, // 20 (Strong breakout response)
  { open: 0.32, close: 0.38, low: 0.30, high: 0.40 }, // 21
  { open: 0.38, close: 0.48, low: 0.36, high: 0.50 }, // 22 (Huge green momentum)
  { open: 0.48, close: 0.44, low: 0.42, high: 0.51 }, // 23 (Minor healthy pullback)
  { open: 0.44, close: 0.55, low: 0.42, high: 0.57 }, // 24
  { open: 0.55, close: 0.62, low: 0.53, high: 0.65 }, // 25
  { open: 0.62, close: 0.74, low: 0.60, high: 0.76 }, // 26 (Power rally)
  { open: 0.74, close: 0.70, low: 0.68, high: 0.78 }, // 27
  { open: 0.70, close: 0.82, low: 0.67, high: 0.84 }, // 28
  { open: 0.82, close: 0.92, low: 0.80, high: 0.95 }, // 29 (Target success peak!)
];

// Single Inline Schema representing overall customization parameters


export type NasdaqTradeAnimationProps = Record<string, any>;

const GridBackground: React.FC = () => {
  const rows = 12;
  const cols = 18;
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        opacity: 0.25,
        transition: "none",
      }}
    >
      {/* Horizontal grid lines */}
      {Array.from({ length: rows }).map((_, r) => (
        <div
          key={`h-${r}`}
          style={{
            width: "100%",
            height: 1,
            backgroundColor: "rgba(255, 255, 255, 0.04)",
            position: "absolute",
            top: `${(r / (rows - 1)) * 100}%`,
            transition: "none",
          }}
        />
      ))}
      {/* Vertical grid lines */}
      {Array.from({ length: cols }).map((_, c) => (
        <div
          key={`v-${c}`}
          style={{
            height: "100%",
            width: 1,
            backgroundColor: "rgba(255, 255, 255, 0.04)",
            position: "absolute",
            left: `${(c / (cols - 1)) * 100}%`,
            transition: "none",
          }}
        />
      ))}
    </div>
  );
};

const NasdaqTradeAnimation: React.FC<NasdaqTradeAnimationProps> = ({
  backgroundColor = "#070c14",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#00e5ff",
  accentColor = "#4a5a70",
  titlePart1 = "BETTER",
  titlePart2 = "ENTRIES",
  tradeLabelText = "TRADE ENTERED",
  candleGlowIntensity = 0.8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  // Render configuration variables
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive frame multiplier to maintain relative timing across dynamic durations
  const scaleFrame = (targetFrame: number) => {
    return Math.round((targetFrame / 240) * totalFrames);
  };

  // Timing milestones
  const historyStart = scaleFrame(5);
  const historyEnd = scaleFrame(50);
  const entryFrame = scaleFrame(60);
  const lineDrawStart = scaleFrame(65);
  const lineDrawEnd = scaleFrame(75);
  const boxPopFrame = scaleFrame(72);
  const breakoutStart = scaleFrame(80);
  const breakoutEnd = scaleFrame(140);
  const text1Pop = scaleFrame(85);
  const text2Pop = scaleFrame(95);
  const underlineStart = scaleFrame(105);
  const underlineEnd = scaleFrame(125);

  // Geometric layout parameters for original visual percentage match
  const chartLeft = width * 0.32;
  const chartWidth = width * 0.61;
  const chartBottom = height * 0.88;
  const chartHeight = height * 0.78;

  const entryCandleX = chartLeft + (19 / 29) * chartWidth;
  // Position of glowing entry target dot corresponding to the close of candle 19
  const entryCandleY = chartBottom - CANDLE_DATA[19].close * chartHeight;

  // Camera Zoom in effect when the trade enters - zoomed in closer for dynamic impact
  const zoomSpring = spring({
    frame: frame - entryFrame,
    fps,
    config: { damping: 18, mass: 0.9, stiffness: 60 },
  });
  const zoomScale = interpolate(zoomSpring, [0, 1], [1, 1.85], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Glow transition around entry zone
  const glowSpring = spring({
    frame: frame - entryFrame,
    fps,
    config: { damping: 20 },
  });
  const glowOpacity = interpolate(glowSpring, [0, 1], [0.03, 0.16]);
  const glowRadius = interpolate(glowSpring, [0, 1], [width * 0.10, width * 0.32]);

  // Rippling animation pulses after trade execution
  const activeRipple = frame >= entryFrame;
  const pulseFactor = activeRipple ? (frame - entryFrame) : 0;
  const pulse1 = (pulseFactor / 30) % 1;
  const pulse2 = ((pulseFactor - 10) / 30) % 1;

  // "TRADE ENTERED" connector line animation
  const lineProgress = interpolate(frame, [lineDrawStart, lineDrawEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const connectorLineLength = height * 0.18;

  // "TRADE ENTERED" tag popup scaling
  const boxScale = spring({
    frame: frame - boxPopFrame,
    fps,
    config: { damping: 11, mass: 0.6 },
  });

  // Left texts animations
  const text1Scale = spring({
    frame: frame - text1Pop,
    fps,
    config: { damping: 12, mass: 0.5 },
  });
  const text2Scale = spring({
    frame: frame - text2Pop,
    fps,
    config: { damping: 12, mass: 0.5 },
  });

  const text1Opacity = interpolate(frame, [text1Pop, text1Pop + 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const text2Opacity = interpolate(frame, [text2Pop, text2Pop + 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const underlineProgress = interpolate(frame, [underlineStart, underlineEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: outfitFamily, overflow: "hidden" }}>
      {/* Zoomable Viewport Container centered on entry coordinate */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${zoomScale})`,
          transformOrigin: `${entryCandleX}px ${entryCandleY}px`,
          transition: "none",
        }}
      >
        {/* Sci-fi Bloomberg-style background grid lines */}
        <GridBackground />

        {/* Radial neon glow situated directly underneath the entry marker */}
        {activeRipple && (
          <div
            style={{
              position: "absolute",
              left: entryCandleX - glowRadius,
              top: entryCandleY - glowRadius,
              width: glowRadius * 2,
              height: glowRadius * 2,
              borderRadius: "50%",
              background: `radial-gradient(circle, ${primaryColor}1d 0%, ${primaryColor}00 70%)`,
              opacity: glowOpacity,
              pointerEvents: "none",
              transition: "none",
            }}
          />
        )}

        {/* Chart Candlesticks Canvas Layer */}
        {CANDLE_DATA.map((candle, i) => {
          let isRevealed = false;
          let progress = 0;

          if (i < 19) {
            // Historical candle progressive drawing
            const candleStart = historyStart + i * ((historyEnd - historyStart) / 19);
            progress = interpolate(frame, [candleStart, candleStart + scaleFrame(8)], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            isRevealed = progress > 0;
          } else if (i === 19) {
            // Trigger entry point candle
            progress = interpolate(frame, [entryFrame, entryFrame + scaleFrame(6)], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            isRevealed = progress > 0;
          } else {
            // Future successful breakouts
            const candleStart = breakoutStart + (i - 20) * ((breakoutEnd - breakoutStart) / 10);
            progress = interpolate(frame, [candleStart, candleStart + scaleFrame(6)], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            isRevealed = progress > 0;
          }

          if (!isRevealed) return null;

          const candleWidth = (chartWidth / 30) * 0.65;
          const cx = chartLeft + (i / 29) * chartWidth;

          const candleScaleY = interpolate(progress, [0, 1], [0, 1]);
          const candleOpacity = interpolate(progress, [0, 1], [0, 1]);

          // Mapping normalized boundaries [0, 1] to chart coordinate container
          const highY = chartBottom - candle.high * chartHeight;
          const lowY = chartBottom - candle.low * chartHeight;
          const openY = chartBottom - candle.open * chartHeight;
          const closeY = chartBottom - candle.close * chartHeight;

          const bodyTop = Math.min(openY, closeY);
          const bodyBottom = Math.max(openY, closeY);
          const bodyHeight = Math.max(2, bodyBottom - bodyTop);

          // Styling logic depending on timeline execution phase (Past: Slate vs Future: Electric Cyan)
          let isFuture = i >= 19;
          let color = "rgba(100, 115, 130, 0.4)";
          let filter = "none";

          if (isFuture) {
            if (i === 19) {
              const triggerProgress = interpolate(frame, [entryFrame, entryFrame + scaleFrame(12)], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
              color = interpolateColors(
                triggerProgress,
                [0, 1],
                ["rgba(100, 115, 130, 0.4)", primaryColor]
              );
              if (triggerProgress > 0) {
                filter = `drop-shadow(0 0 ${8 * triggerProgress * candleGlowIntensity}px ${primaryColor})`;
              }
            } else {
              color = primaryColor;
              filter = `drop-shadow(0 0 ${8 * candleGlowIntensity}px ${primaryColor})`;
            }
          }

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: cx - candleWidth / 2,
                width: candleWidth,
                height: chartHeight,
                top: chartBottom - chartHeight,
                opacity: candleOpacity,
                transform: `scaleY(${candleScaleY})`,
                transformOrigin: "bottom center",
                transition: "none",
              }}
            >
              {/* Upper & lower wicks */}
              <div
                style={{
                  position: "absolute",
                  left: candleWidth / 2 - 1,
                  width: 2,
                  top: highY - (chartBottom - chartHeight),
                  height: lowY - highY,
                  backgroundColor: color,
                  filter,
                  transition: "none",
                }}
              />

              {/* Candle real body */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  width: candleWidth,
                  top: bodyTop - (chartBottom - chartHeight),
                  height: bodyHeight,
                  backgroundColor: color,
                  borderRadius: 2.5,
                  filter,
                  transition: "none",
                }}
              />
            </div>
          );
        })}

        {/* Concentric active ripple waves centered at entry coordinate */}
        {activeRipple && (
          <div style={{ position: "absolute", left: entryCandleX, top: entryCandleY, pointerEvents: "none" }}>
            {pulse1 >= 0 && (
              <div
                style={{
                  position: "absolute",
                  left: -((pulse1 * 70) / 2),
                  top: -((pulse1 * 70) / 2),
                  width: pulse1 * 70,
                  height: pulse1 * 70,
                  borderRadius: "50%",
                  border: `2px solid ${primaryColor}`,
                  opacity: 1 - pulse1,
                  transition: "none",
                }}
              />
            )}
            {pulse2 >= 0 && (
              <div
                style={{
                  position: "absolute",
                  left: -((pulse2 * 70) / 2),
                  top: -((pulse2 * 70) / 2),
                  width: pulse2 * 70,
                  height: pulse2 * 70,
                  borderRadius: "50%",
                  border: `2px solid ${primaryColor}`,
                  opacity: 1 - pulse2,
                  transition: "none",
                }}
              />
            )}
          </div>
        )}

        {/* Target marker dot */}
        {frame >= entryFrame && (
          <div
            style={{
              position: "absolute",
              left: entryCandleX - 7,
              top: entryCandleY - 7,
              width: 14,
              height: 14,
              borderRadius: "50%",
              backgroundColor: primaryColor,
              boxShadow: `0 0 12px ${primaryColor}`,
              zIndex: 15,
              transition: "none",
            }}
          />
        )}

        {/* Connector line dropping down to labels */}
        {frame >= lineDrawStart && (
          <div
            style={{
              position: "absolute",
              left: entryCandleX - 1,
              top: entryCandleY,
              width: 2,
              height: lineProgress * connectorLineLength,
              backgroundColor: primaryColor,
              boxShadow: `0 0 6px ${primaryColor}80`,
              zIndex: 5,
              transition: "none",
            }}
          />
        )}

        {/* Interactive "TRADE ENTERED" tag */}
        {frame >= boxPopFrame && (
          <div
            style={{
              position: "absolute",
              left: entryCandleX,
              top: entryCandleY + connectorLineLength,
              transform: `translate(-50%, 0) scale(${boxScale})`,
              transformOrigin: "top center",
              zIndex: 14,
              transition: "none",
            }}
          >
            <div
              style={{
                backgroundColor: primaryColor,
                color: "#050a12",
                padding: `${height * 0.008}px ${width * 0.015}px`,
                fontSize: height * 0.015,
                fontWeight: "900",
                letterSpacing: "1px",
                whiteSpace: "nowrap",
                boxShadow: `0 0 16px ${primaryColor}80`,
                borderRadius: 3,
                transition: "none",
              }}
            >
              {tradeLabelText}
            </div>
          </div>
        )}
      </div>

      {/* Left side text column */}
      <div
        style={{
          position: "absolute",
          left: width * 0.065,
          top: height * 0.32,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          zIndex: 10,
          transition: "none",
        }}
      >
        <div
          style={{
            fontSize: height * 0.13,
            fontWeight: 900,
            color: "#ffffff",
            lineHeight: 0.9,
            letterSpacing: "-2px",
            opacity: text1Opacity,
            transform: `scale(${interpolate(text1Scale, [0, 1], [0.5, 1])})`,
            transformOrigin: "left center",
            transition: "none",
          }}
        >
          {titlePart1}
        </div>
        <div
          style={{
            fontSize: height * 0.13,
            fontWeight: 900,
            color: primaryColor,
            lineHeight: 0.9,
            letterSpacing: "-2px",
            textShadow: `0 0 15px ${primaryColor}3a`,
            opacity: text2Opacity,
            transform: `scale(${interpolate(text2Scale, [0, 1], [0.5, 1])})`,
            transformOrigin: "left center",
            transition: "none",
          }}
        >
          {titlePart2}
        </div>

        {/* Decorative sliding progress/underline accent bar */}
        <div
          style={{
            position: "relative",
            marginTop: height * 0.04,
            width: width * 0.35,
            height: 3,
            backgroundColor: "rgba(255, 255, 255, 0.07)",
            transition: "none",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              height: "100%",
              width: `${underlineProgress * 28}%`,
              backgroundColor: primaryColor,
              boxShadow: `0 0 8px ${primaryColor}`,
              transition: "none",
            }}
          />
        </div>
      </div>

      {/* Left-top cosmetic plus marker */}
      <svg
        width={Math.min(width, height) * 0.024}
        height={Math.min(width, height) * 0.024}
        viewBox="0 0 24 24"
        style={{
          position: "absolute",
          left: width * 0.065,
          top: height * 0.18,
          opacity: 0.2,
          transition: "none",
        }}
      >
        <line x1="12" y1="4" x2="12" y2="20" stroke="white" strokeWidth="2" />
        <line x1="4" y1="12" x2="20" y2="12" stroke="white" strokeWidth="2" />
      </svg>

      {/* Left-bottom decorative dot grids */}
      <div
        style={{
          position: "absolute",
          left: width * 0.065,
          top: height * 0.88,
          display: "grid",
          gridTemplateColumns: "repeat(6, 1fr)",
          gap: "8px",
          opacity: 0.18,
          transition: "none",
        }}
      >
        {Array.from({ length: 12 }).map((_, idx) => (
          <div
            key={idx}
            style={{
              width: Math.min(width, height) * 0.005,
              height: Math.min(width, height) * 0.005,
              backgroundColor: "#ffffff",
              borderRadius: "50%",
              transition: "none",
            }}
          />
        ))}
      </div>

      {/* Bottom right subtle indicator */}
      <div
        style={{
          position: "absolute",
          right: width * 0.07,
          bottom: height * 0.08,
          width: width * 0.09,
          height: 2,
          backgroundColor: "rgba(255, 255, 255, 0.12)",
          transition: "none",
        }}
      >
        <div
          style={{
            width: "35%",
            height: "100%",
            backgroundColor: primaryColor,
            boxShadow: `0 0 6px ${primaryColor}`,
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default NasdaqTradeAnimation;